                    add('embedding',r=r,c=c,v=cfg.vocab,type=info.type)
                    add('linear',r=1,k=k,o=o,type=info.type)
                elif info.name=='output.weight':add('linear',r=1,k=k,o=o,type=info.type)
                else:
